import React from 'react';
import { Link } from 'react-router-dom';

function Navbar({ user, cart = [], onLogout }) {
    const cartCount = cart.reduce((count, item) => count + item.quantity, 0);

    return (
        <nav className="navbar bg-green-500 p-4 text-white shadow-md">
            <div className="container mx-auto flex justify-between items-center">
                <Link to="/" className="text-2xl font-bold text-white hover:underline">
                    MyShop
                </Link>
                <div className="nav-links flex space-x-6">
                    <Link to="/products" className="text-lg hover:underline">
                        Products
                    </Link>
                    <Link to="/cart" className="text-lg hover:underline">
                        Cart ({cartCount})
                    </Link>
                    {user ? (
                        <>
                            <Link to="/orders" className="text-lg hover:underline">
                                Orders
                            </Link>
                            <span className="font-medium">Hello, {user.name}</span>
                            <button
                                onClick={onLogout}
                                className="bg-red-500 text-white px-4 py-1 rounded hover:bg-red-600 transition duration-200"
                            >
                                Logout
                            </button>
                        </>
                    ) : (
                        <Link
                            to="/login"
                            className="bg-white text-green-500 px-4 py-1 rounded hover:bg-green-600 hover:text-white transition duration-200"
                        >
                            Login
                        </Link>
                    )}
                </div>
            </div>
        </nav>
    );
}

// Ensure this default export is present
export default Navbar;
